"""A fictional practical examination growing from the 1977 admissions debate."""

from game.witness_reform import choice, scene


def add_tailor(chapter):
    chapter["history"] += " 《借一只袖子》里由考生出题的试场、丁小满和天佑一家，以及这件衣服二十年后的去向，均属架空。"
    chapter["scenes"][0]["choices"].append(choice(
        "tailor_exam", "拆开用蓝布缝的信封，看看一个裁缝学徒要怎样考大学老师",
        "八月的会开罢，桌角多了一只布信封。没有邮票。修理工邵梅替隔壁裁缝店的姑娘捎来的。封口用活线一扽就开，里面只装了一只袖子。", "air_begin"))
    chapter["scenes"].extend(SCENES)


